fn q05_key_nation_map_batch_typed(
    keys: &ArrayRef,
    nationkeys: &ArrayRef,
    nation_filter: &AdaptiveI64Set,
    output: &mut FastHashMap<i64, i64>,
) -> bool {
    let (Some(keys), Some(nationkeys)) = (
        keys.as_any().downcast_ref::<Int64Array>(),
        nationkeys.as_any().downcast_ref::<Int64Array>(),
    ) else {
        return false;
    };
    if keys.null_count() == 0 && nationkeys.null_count() == 0 {
        let key_values = keys.values().as_ref();
        let nation_values = nationkeys.values().as_ref();
        if let Some(nation_contains) = nation_filter.dense_contains_slice() {
            for row in 0..key_values.len() {
                let nationkey = nation_values[row];
                if usize::try_from(nationkey)
                    .ok()
                    .and_then(|index| nation_contains.get(index))
                    .copied()
                    .unwrap_or(false)
                {
                    output.insert(key_values[row], nationkey);
                }
            }
            return true;
        }
        for row in 0..key_values.len() {
            let nationkey = nation_values[row];
            if nation_filter.contains(nationkey) {
                output.insert(key_values[row], nationkey);
            }
        }
        return true;
    }
    for row in 0..keys.len() {
        if keys.is_null(row) || nationkeys.is_null(row) {
            continue;
        }
        let nationkey = nationkeys.value(row);
        if nation_filter.contains(nationkey) {
            output.insert(keys.value(row), nationkey);
        }
    }
    true
}

async fn q05_order_customer_nations(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<i64, i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "o_orderkey".to_string(),
                "o_custkey".to_string(),
                "o_orderdate".to_string(),
            ]),
            None,
        )
        .await?;
    let customer_nations = Arc::new(AdaptiveI64Map::from_hash(customer_nations.clone()));
    parallel_batch_fold_view_chunks(
        &mut stream,
        4,
        || fast_hash_map::<i64, i64>(),
        move |view, orders| {
            merge_maps(
                orders,
                q05_order_customer_nations_view(view, &customer_nations, start_days, end_days)?,
            );
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<i64, i64>(),
        merge_maps,
        "Q05 order customer nations",
    )
}

fn q05_order_customer_nations_batch(
    batch: RecordBatch,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<i64, i64>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    let orderdates = batch_column(&batch, "o_orderdate")?;
    if let Some(orders) = q05_order_customer_nations_batch_typed(
        orderkeys,
        custkeys,
        orderdates,
        customer_nations,
        start_days,
        end_days,
    ) {
        return Ok(orders);
    }
    let mut orders = fast_hash_map::<i64, i64>();
    for row in 0..batch.num_rows() {
        let Some(orderdate) = date32_value(orderdates, row)? else {
            continue;
        };
        if orderdate < start_days || orderdate >= end_days {
            continue;
        }
        let (Some(orderkey), Some(custkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(custkeys, row)?,
        ) else {
            continue;
        };
        if let Some(nationkey) = customer_nations.get(custkey) {
            orders.insert(orderkey, nationkey);
        }
    }
    Ok(orders)
}

fn q05_order_customer_nations_view(
    view: BatchView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<i64, i64>> {
    if view.num_columns() == 3
        && let (Some(orderkeys), Some(custkeys), Some(orderdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
        )
    {
        return Ok(q05_order_customer_nations_vectors(
            orderkeys,
            custkeys,
            orderdates,
            customer_nations,
            start_days,
            end_days,
        ));
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q05 order customer nation raw vector columns have unsupported types".to_string(),
        ));
    };
    q05_order_customer_nations_batch(batch.clone(), customer_nations, start_days, end_days)
}

fn q05_order_customer_nations_vectors(
    orderkeys: I64VectorView<'_>,
    custkeys: I64VectorView<'_>,
    orderdates: Date32VectorView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> FastHashMap<i64, i64> {
    let mut orders = fast_hash_map::<i64, i64>();
    if let (Some(orderkey_values), Some(custkey_values), Some(orderdate_values)) = (
        orderkeys.values_if_null_free(),
        custkeys.values_if_null_free(),
        orderdates.values_if_null_free(),
    ) {
        if let Some((nation_values, nation_present)) = customer_nations.dense_slices() {
            for row in 0..orderkey_values.len() {
                let orderdate = orderdate_values[row];
                if orderdate < start_days || orderdate >= end_days {
                    continue;
                }
                let Ok(custkey) = usize::try_from(custkey_values[row]) else {
                    continue;
                };
                if nation_present.get(custkey).copied().unwrap_or(false) {
                    orders.insert(orderkey_values[row], nation_values[custkey]);
                }
            }
            return orders;
        }
        for row in 0..orderkey_values.len() {
            let orderdate = orderdate_values[row];
            if orderdate < start_days || orderdate >= end_days {
                continue;
            }
            if let Some(nationkey) = customer_nations.get(custkey_values[row]) {
                orders.insert(orderkey_values[row], nationkey);
            }
        }
        return orders;
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) || orderdates.is_null(row) {
            continue;
        }
        let orderdate = orderdates.value(row);
        if orderdate < start_days || orderdate >= end_days {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    orders
}

fn q05_order_customer_nations_batch_typed(
    orderkeys: &ArrayRef,
    custkeys: &ArrayRef,
    orderdates: &ArrayRef,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Option<FastHashMap<i64, i64>> {
    let (Some(orderkeys), Some(custkeys), Some(orderdates)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        custkeys.as_any().downcast_ref::<Int64Array>(),
        orderdates.as_any().downcast_ref::<Date32Array>(),
    ) else {
        return None;
    };
    let mut orders = fast_hash_map::<i64, i64>();
    if orderkeys.null_count() == 0 && custkeys.null_count() == 0 && orderdates.null_count() == 0 {
        for row in 0..orderkeys.len() {
            let orderdate = orderdates.value(row);
            if orderdate < start_days || orderdate >= end_days {
                continue;
            }
            if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
                orders.insert(orderkeys.value(row), nationkey);
            }
        }
        return Some(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) || orderdates.is_null(row) {
            continue;
        }
        let orderdate = orderdates.value(row);
        if orderdate < start_days || orderdate >= end_days {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    Some(orders)
}

struct Q05Row {
    n_name: String,
    revenue: f64,
}

async fn q05_revenue_by_nation(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &FastHashMap<i64, i64>,
    nation_names: &HashMap<i64, String>,
) -> Result<Vec<Q05Row>> {
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_suppkey".to_string(),
        "l_extendedprice".to_string(),
        "l_discount".to_string(),
    ]);
    let pruning_predicates = if let Some((min_key, max_key)) =
        selective_i64_key_range(order_customer_nations.keys().copied())
    {
        i64_range_pruning_predicates("l_orderkey", min_key, max_key)
    } else {
        Vec::new()
    };
    let order_customer_nations = Arc::new(order_customer_nations.clone());
    let supplier_nations = Arc::new(AdaptiveI64Map::from_hash(supplier_nations.clone()));
    let groups = if q05_row_group_map_enabled() {
        let order_customer_nations_for_scan = order_customer_nations.clone();
        let supplier_nations_for_scan = supplier_nations.clone();
        if let Some(partials) = engine
            .parquet_row_group_map_pruned_view(
                path.clone(),
                batch_size,
                projection.clone(),
                pruning_predicates.clone(),
                q05_row_group_map_chunk(),
                fast_hash_map::<i64, f64>,
                move |view, groups| {
                    merge_f64_groups(
                        groups,
                        q05_revenue_by_nation_projected_view(
                            view,
                            &order_customer_nations_for_scan,
                            &supplier_nations_for_scan,
                        )?,
                    );
                    Ok(Some(()))
                },
                |groups| Ok(Some(groups)),
            )
            .await?
        {
            let mut groups = fast_hash_map::<i64, f64>();
            for partial in partials {
                merge_f64_groups(&mut groups, partial);
            }
            groups
        } else {
            q05_revenue_by_nation_stream(
                engine,
                path,
                batch_size,
                projection,
                pruning_predicates,
                order_customer_nations,
                supplier_nations,
            )
            .await?
        }
    } else {
        q05_revenue_by_nation_stream(
            engine,
            path,
            batch_size,
            projection,
            pruning_predicates,
            order_customer_nations,
            supplier_nations,
        )
        .await?
    };
    let mut rows = groups
        .into_iter()
        .filter_map(|(nationkey, revenue)| {
            nation_names.get(&nationkey).map(|n_name| Q05Row {
                n_name: n_name.clone(),
                revenue,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .revenue
            .partial_cmp(&left.revenue)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    Ok(rows)
}

async fn q05_revenue_by_nation_stream(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    pruning_predicates: Vec<Expr>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
) -> Result<FastHashMap<i64, f64>> {
    let mut stream = if pruning_predicates.is_empty() {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    } else {
        engine
            .scan_parquet_batches_pruned(path, batch_size, projection, pruning_predicates)
            .await?
    };
    parallel_batch_fold_view_chunks(
        &mut stream,
        join_aggregate_chunk_size(),
        || fast_hash_map::<i64, f64>(),
        move |view, groups| {
            merge_f64_groups(
                groups,
                q05_revenue_by_nation_projected_view(
                    view,
                    &order_customer_nations,
                    &supplier_nations,
                )?,
            );
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<i64, f64>(),
        merge_f64_groups,
        "Q05 revenue aggregate",
    )
}

fn q05_row_group_map_enabled() -> bool {
    std::env::var_os("DODAM_Q05_DISABLE_ROW_GROUP_MAP").is_none()
}

fn q05_row_group_map_chunk() -> usize {
    std::env::var("DODAM_Q05_ROW_GROUP_MAP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q05_revenue_by_nation_batch(
    batch: RecordBatch,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, f64>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let Some(groups) = q05_revenue_by_nation_typed(
        orderkeys,
        suppkeys,
        extendedprices,
        discounts,
        order_customer_nations,
        supplier_nations,
    )? {
        return Ok(groups);
    }
    let mut groups = fast_hash_map::<i64, f64>();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(suppkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
        ) else {
            continue;
        };
        let (Some(customer_nation), Some(supplier_nation)) = (
            order_customer_nations.get(&orderkey).copied(),
            supplier_nations.get(suppkey),
        ) else {
            continue;
        };
        if customer_nation != supplier_nation {
            continue;
        }
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        *groups.entry(customer_nation).or_insert(0.0) += extendedprice * (1.0 - discount);
    }
    Ok(groups)
}

#[allow(dead_code)]
fn q05_revenue_by_nation_projected_batch(
    batch: RecordBatch,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, f64>> {
    if batch.num_columns() == 4
        && let Some(groups) = q05_revenue_by_nation_typed(
            batch.column(0),
            batch.column(1),
            batch.column(2),
            batch.column(3),
            order_customer_nations,
            supplier_nations,
        )?
    {
        return Ok(groups);
    }
    q05_revenue_by_nation_batch(batch, order_customer_nations, supplier_nations)
}

fn q05_revenue_by_nation_projected_view(
    view: BatchView<'_>,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, f64>> {
    if view.num_columns() == 4
        && let (Some(orderkeys), Some(suppkeys), Some(extendedprices), Some(discounts)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.decimal128_vector(2),
            view.decimal128_vector(3),
        )
    {
        return Ok(q05_revenue_by_nation_vector(
            orderkeys,
            suppkeys,
            extendedprices,
            discounts,
            order_customer_nations,
            supplier_nations,
        ));
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q05 revenue raw vector columns have unsupported types".to_string(),
        ));
    };
    q05_revenue_by_nation_batch(batch.clone(), order_customer_nations, supplier_nations)
}

fn q05_revenue_by_nation_vector(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &AdaptiveI64Map<i64>,
) -> FastHashMap<i64, f64> {
    let mut groups = fast_hash_map::<i64, f64>();
    if let (Some(orderkey_values), Some(suppkey_values)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
    ) && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        if let Some((supplier_nation_values, supplier_nation_present)) =
            supplier_nations.dense_slices()
        {
            for row in 0..orderkey_values.len() {
                let orderkey = orderkey_values[row];
                let Some(customer_nation) = order_customer_nations.get(&orderkey).copied() else {
                    continue;
                };
                let Ok(suppkey) = usize::try_from(suppkey_values[row]) else {
                    continue;
                };
                if supplier_nation_present
                    .get(suppkey)
                    .copied()
                    .unwrap_or(false)
                    && supplier_nation_values[suppkey] == customer_nation
                {
                    *groups.entry(customer_nation).or_insert(0.0) += decimal_discounted_revenue_raw(
                        extendedprice_values[row],
                        discount_values[row],
                        discount_scale,
                        revenue_scale,
                    );
                }
            }
            return groups;
        }
        for row in 0..orderkey_values.len() {
            let orderkey = orderkey_values[row];
            let suppkey = suppkey_values[row];
            let (Some(customer_nation), Some(supplier_nation)) = (
                order_customer_nations.get(&orderkey).copied(),
                supplier_nations.get(suppkey),
            ) else {
                continue;
            };
            if customer_nation == supplier_nation {
                *groups.entry(customer_nation).or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
        }
        return groups;
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let orderkey = orderkeys.value(row);
        let suppkey = suppkeys.value(row);
        let (Some(customer_nation), Some(supplier_nation)) = (
            order_customer_nations.get(&orderkey).copied(),
            supplier_nations.get(suppkey),
        ) else {
            continue;
        };
        if customer_nation == supplier_nation {
            *groups.entry(customer_nation).or_insert(0.0) +=
                extendedprices.value(row) * (1.0 - discounts.value(row));
        }
    }
    groups
}

fn q05_revenue_by_nation_typed(
    orderkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    extendedprices: &ArrayRef,
    discounts: &ArrayRef,
    order_customer_nations: &FastHashMap<i64, i64>,
    supplier_nations: &AdaptiveI64Map<i64>,
) -> Result<Option<FastHashMap<i64, f64>>> {
    let (Some(orderkeys), Some(suppkeys), Some(extendedprices), Some(discounts)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    let mut groups = fast_hash_map::<i64, f64>();
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let (discount_scale, revenue_scale) =
            decimal_discounted_revenue_scales(extendedprices, discounts);
        for row in 0..orderkeys.len() {
            let orderkey = orderkey_values[row];
            let suppkey = suppkey_values[row];
            let (Some(customer_nation), Some(supplier_nation)) = (
                order_customer_nations.get(&orderkey).copied(),
                supplier_nations.get(suppkey),
            ) else {
                continue;
            };
            if customer_nation == supplier_nation {
                *groups.entry(customer_nation).or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
        }
        return Ok(Some(groups));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let orderkey = orderkeys.value(row);
        let suppkey = suppkeys.value(row);
        let (Some(customer_nation), Some(supplier_nation)) = (
            order_customer_nations.get(&orderkey).copied(),
            supplier_nations.get(suppkey),
        ) else {
            continue;
        };
        if customer_nation == supplier_nation {
            *groups.entry(customer_nation).or_insert(0.0) +=
                extendedprices.value(row) * (1.0 - discounts.value(row));
        }
    }
    Ok(Some(groups))
}

fn q05_output(rows: Vec<Q05Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("n_name", DataType::Utf8, false),
            Field::new("revenue", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.n_name.as_str()),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.revenue),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

async fn try_execute_q06_forecast_revenue_fast(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !q06_shape(select, query, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let table = parse_from(select)?;
    if !table_ref_alias_or_name(&table).eq_ignore_ascii_case("lineitem") {
        return Ok(None);
    }
    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some((start_days, end_days)) = date_range_bounds(&conjuncts, "l_shipdate")? else {
        return Ok(None);
    };
    let Some((discount_low, discount_high)) = numeric_between_bounds(&conjuncts, "l_discount")?
    else {
        return Ok(None);
    };
    let Some(quantity_limit) = upper_numeric_bound(&conjuncts, "l_quantity")? else {
        return Ok(None);
    };
    let Some((sum, count)) = q06_revenue_sum(
        engine,
        table.path,
        batch_size,
        start_days,
        end_days,
        discount_low,
        discount_high,
        quantity_limit,
    )
    .await?
    else {
        return Ok(None);
    };
    Ok(Some(q17_output(
        "revenue".to_string(),
        (count > 0).then_some(sum),
    )?))
}

fn q06_shape(select: &Select, query: &Query, selection: &SqlExpr) -> bool {
    if !matches!(parse_limit(query), Ok(None)) {
        return false;
    }
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let selection = selection.to_string().to_ascii_lowercase();
    select.projection.len() == 1
        && projection.contains("sum(")
        && projection.contains("l_extendedprice")
        && projection.contains("l_discount")
        && selection.contains("l_shipdate")
        && selection.contains("l_discount")
        && selection.contains("l_quantity")
}

fn numeric_between_bounds(conjuncts: &[SqlExpr], column: &str) -> Result<Option<(f64, f64)>> {
    for conjunct in conjuncts {
        let SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } = conjunct
        else {
            continue;
        };
        if *negated || !sql_expr_column_matches(expr, column) {
            continue;
        }
        return Ok(Some((
            literal_as_f64(&sql_literal_value(low)?)?,
            literal_as_f64(&sql_literal_value(high)?)?,
        )));
    }
    Ok(None)
}

fn upper_numeric_bound(conjuncts: &[SqlExpr], column: &str) -> Result<Option<f64>> {
    let mut bound = None;
    for conjunct in conjuncts {
        let SqlExpr::BinaryOp { left, op, right } = conjunct else {
            continue;
        };
        if matches!(op, BinaryOperator::Lt | BinaryOperator::LtEq)
            && sql_expr_column_matches(left, column)
        {
            bound = Some(literal_as_f64(&sql_literal_value(right)?)?);
        } else if matches!(op, BinaryOperator::Gt | BinaryOperator::GtEq)
            && sql_expr_column_matches(right, column)
        {
            bound = Some(literal_as_f64(&sql_literal_value(left)?)?);
        }
    }
    Ok(bound)
}

fn lower_numeric_bound(conjuncts: &[SqlExpr], column: &str) -> Result<Option<f64>> {
    let mut bound = None;
    for conjunct in conjuncts {
        let SqlExpr::BinaryOp { left, op, right } = conjunct else {
            continue;
        };
        if matches!(op, BinaryOperator::Gt | BinaryOperator::GtEq)
            && sql_expr_column_matches(left, column)
        {
            bound = Some(literal_as_f64(&sql_literal_value(right)?)?);
        } else if matches!(op, BinaryOperator::Lt | BinaryOperator::LtEq)
            && sql_expr_column_matches(right, column)
        {
            bound = Some(literal_as_f64(&sql_literal_value(left)?)?);
        }
    }
    Ok(bound)
}

async fn q06_revenue_sum(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<(f64, u64)>> {
    if std::env::var_os("DODAM_Q06_ENABLE_LATE_MATERIALIZE").is_some() {
        if let Some(result) = engine
            .q06_late_materialized_revenue_sum(
                path.clone(),
                batch_size,
                start_days,
                end_days,
                discount_low,
                discount_high,
                quantity_limit,
            )
            .await?
        {
            return Ok(Some(result));
        }
    }
    if q06_direct_primitive_enabled()
        && let Some(result) = q06_revenue_sum_direct_primitive(
            engine,
            path.clone(),
            batch_size,
            start_days,
            end_days,
            discount_low,
            discount_high,
            quantity_limit,
        )?
    {
        return Ok(Some(result));
    }
    let row_filter_enabled = q06_row_filter_enabled();
    let projection = if row_filter_enabled {
        Projection::Columns(vec![
            "l_discount".to_string(),
            "l_extendedprice".to_string(),
        ])
    } else {
        Projection::Columns(vec![
            "l_shipdate".to_string(),
            "l_discount".to_string(),
            "l_quantity".to_string(),
            "l_extendedprice".to_string(),
        ])
    };
    if !row_filter_enabled {
        return engine
            .parquet_scan_accumulate_chunks_view(
                path,
                batch_size,
                projection,
                scan_aggregate_row_group_chunk(),
                q06_revenue_chunk_size(),
                scan_aggregate_fusion_enabled(),
                || Some((0.0, 0_u64)),
                || Some((0.0, 0_u64)),
                move |view, total| {
                    let batch = q06_revenue_sum_view(
                        view,
                        start_days,
                        end_days,
                        discount_low,
                        discount_high,
                        quantity_limit,
                    )?;
                    if let (Some(total), Some(batch)) = (total.as_mut(), batch) {
                        total.0 += batch.0;
                        total.1 += batch.1;
                    } else {
                        *total = None;
                    }
                    Ok(Some(()))
                },
                |total, batch| {
                    if let (Some(total), Some(batch)) = (total.as_mut(), batch) {
                        total.0 += batch.0;
                        total.1 += batch.1;
                    } else {
                        *total = None;
                    }
                },
                "Q06 revenue sum",
            )
            .await;
    }

    let mut stream = {
        engine
            .scan_parquet_batches_row_filtered(
                path,
                batch_size,
                projection,
                q06_row_filter_predicates(
                    start_days,
                    end_days,
                    discount_low,
                    discount_high,
                    quantity_limit,
                ),
            )
            .await?
    };
    parallel_batch_fold_view_chunks(
        &mut stream,
        q06_revenue_chunk_size(),
        || Some((0.0, 0_u64)),
        move |view, total: &mut Option<(f64, u64)>| {
            let batch_result = if row_filter_enabled {
                q06_filtered_revenue_sum_view(view)?
            } else {
                q06_revenue_sum_view(
                    view,
                    start_days,
                    end_days,
                    discount_low,
                    discount_high,
                    quantity_limit,
                )?
            };
            if let (Some(total), Some(batch)) = (total.as_mut(), batch_result) {
                total.0 += batch.0;
                total.1 += batch.1;
            } else {
                *total = None;
            }
            Ok(Some(()))
        },
        Ok,
        Some((0.0, 0_u64)),
        |total, batch| {
            if let (Some(total), Some(batch)) = (total.as_mut(), batch) {
                total.0 += batch.0;
                total.1 += batch.1;
            } else {
                *total = None;
            }
        },
        "Q06 revenue sum",
    )
}

fn q06_direct_primitive_enabled() -> bool {
    std::env::var("DODAM_Q06_ENABLE_DIRECT_PRIMITIVE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn q06_direct_primitive_row_group_chunk() -> usize {
    std::env::var("DODAM_Q06_DIRECT_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

#[allow(clippy::too_many_arguments)]
fn q06_revenue_sum_direct_primitive(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<(f64, u64)>> {
    let started = tpch_profile_start();
    let row_groups = (0..engine.parquet_row_group_count(&path)?).collect::<Vec<_>>();
    let chunks = row_groups
        .chunks(q06_direct_primitive_row_group_chunk())
        .map(|chunk| chunk.to_vec())
        .collect::<Vec<_>>();
    let partials = chunks
        .into_par_iter()
        .map(|row_groups| {
            q06_revenue_sum_direct_primitive_chunk(
                engine,
                path.clone(),
                batch_size,
                row_groups,
                start_days,
                end_days,
                discount_low,
                discount_high,
                quantity_limit,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let mut total = (0.0, 0_u64);
    let mut metrics = DirectPrimitiveColumnScanMetrics::default();
    for partial in partials {
        let Some((partial, partial_metrics)) = partial else {
            return Ok(None);
        };
        total.0 += partial.0;
        total.1 += partial.1;
        metrics.row_groups = metrics
            .row_groups
            .saturating_add(partial_metrics.row_groups);
        metrics.batches = metrics.batches.saturating_add(partial_metrics.batches);
        metrics.rows = metrics.rows.saturating_add(partial_metrics.rows);
        metrics.read_nanos = metrics
            .read_nanos
            .saturating_add(partial_metrics.read_nanos);
        metrics.consume_nanos = metrics
            .consume_nanos
            .saturating_add(partial_metrics.consume_nanos);
    }
    if let Some(started) = started {
        eprintln!(
            "[dodam:tpch-profile] Q06 direct_primitive: total={:.3} ms row_groups={} batches={} rows={} read={:.3} ms consume={:.3} ms",
            started.elapsed().as_secs_f64() * 1000.0,
            metrics.row_groups,
            metrics.batches,
            metrics.rows,
            sql_nanos_to_millis(metrics.read_nanos),
            sql_nanos_to_millis(metrics.consume_nanos),
        );
    }
    Ok(Some(total))
}

#[allow(clippy::too_many_arguments)]
fn q06_revenue_sum_direct_primitive_chunk(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    row_groups: Vec<usize>,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<((f64, u64), DirectPrimitiveColumnScanMetrics)>> {
    let specs = [
        DirectPrimitiveColumnSpec {
            name: "l_shipdate",
            column_type: DirectPrimitiveColumnType::Date32,
        },
        DirectPrimitiveColumnSpec {
            name: "l_discount",
            column_type: DirectPrimitiveColumnType::Decimal128Int64 {
                precision: 15,
                scale: 2,
            },
        },
        DirectPrimitiveColumnSpec {
            name: "l_quantity",
            column_type: DirectPrimitiveColumnType::Decimal128Int64 {
                precision: 15,
                scale: 2,
            },
        },
        DirectPrimitiveColumnSpec {
            name: "l_extendedprice",
            column_type: DirectPrimitiveColumnType::Decimal128Int64 {
                precision: 15,
                scale: 2,
            },
        },
    ];
    let mut total = Some((0.0, 0_u64));
    let Some(metrics) = engine.scan_parquet_primitive_columns_view(
        &path,
        batch_size,
        &row_groups,
        &specs,
        |view| {
            let batch = q06_revenue_sum_view(
                view,
                start_days,
                end_days,
                discount_low,
                discount_high,
                quantity_limit,
            )?;
            if let (Some(total), Some(batch)) = (total.as_mut(), batch) {
                total.0 += batch.0;
                total.1 += batch.1;
            } else {
                total = None;
            }
            Ok(())
        },
    )?
    else {
        return Ok(None);
    };
    Ok(total.map(|total| (total, metrics)))
}

fn q06_row_filter_enabled() -> bool {
    std::env::var_os("DODAM_Q06_ROW_FILTER").is_some()
}

fn q06_row_filter_predicates(
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Vec<Expr> {
    let predicates = vec![
        q06_comparison(
            "l_shipdate",
            ComparisonOp::GtEq,
            LiteralValue::Int64(i64::from(start_days)),
        ),
        q06_comparison(
            "l_shipdate",
            ComparisonOp::Lt,
            LiteralValue::Int64(i64::from(end_days)),
        ),
        q06_comparison(
            "l_discount",
            ComparisonOp::GtEq,
            LiteralValue::Float64(discount_low),
        ),
        q06_comparison(
            "l_discount",
            ComparisonOp::LtEq,
            LiteralValue::Float64(discount_high),
        ),
        q06_comparison(
            "l_quantity",
            ComparisonOp::Lt,
            LiteralValue::Float64(quantity_limit),
        ),
    ];
    vec![
        predicates
            .into_iter()
            .reduce(|left, right| Expr::And(Box::new(left), Box::new(right)))
            .expect("q06 row filter predicates"),
    ]
}

fn q06_comparison(column: &str, op: ComparisonOp, value: LiteralValue) -> Expr {
    Expr::Comparison(ComparisonExpr {
        column: column.to_string(),
        op,
        value,
    })
}

fn q06_revenue_chunk_size() -> usize {
    std::env::var("DODAM_Q06_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

fn q06_filtered_revenue_sum_batch(batch: RecordBatch) -> Result<Option<(f64, u64)>> {
    let discounts = batch_column(&batch, "l_discount")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let (Some(discounts), Some(extendedprices)) =
        (decimal_input(discounts)?, decimal_input(extendedprices)?)
    else {
        return Ok(None);
    };
    let mut sum = 0.0;
    let mut count = 0_u64;
    if discounts.null_count() == 0 && extendedprices.null_count() == 0 {
        let revenue_scale = 1.0 / (extendedprices.scale * discounts.scale);
        if discounts.precision <= 18 && extendedprices.precision <= 18 {
            for (&discount, &extendedprice) in discounts
                .raw_values()
                .iter()
                .zip(extendedprices.raw_values())
            {
                sum += (extendedprice as i64 * discount as i64) as f64 * revenue_scale;
                count += 1;
            }
            return Ok(Some((sum, count)));
        }
        for (&discount, &extendedprice) in discounts
            .raw_values()
            .iter()
            .zip(extendedprices.raw_values())
        {
            sum += (extendedprice * discount) as f64 * revenue_scale;
            count += 1;
        }
        return Ok(Some((sum, count)));
    }
    for row in 0..batch.num_rows() {
        if discounts.is_null(row) || extendedprices.is_null(row) {
            continue;
        }
        sum += extendedprices.value(row) * discounts.value(row);
        count += 1;
    }
    Ok(Some((sum, count)))
}

fn q06_filtered_revenue_sum_view(view: BatchView<'_>) -> Result<Option<(f64, u64)>> {
    if view.num_columns() == 2
        && let (Some(discounts), Some(extendedprices)) =
            (view.decimal128_vector(0), view.decimal128_vector(1))
    {
        return q06_filtered_revenue_sum_vectors(discounts, extendedprices, view.num_rows());
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q06_filtered_revenue_sum_batch(batch.clone())
}

fn q06_filtered_revenue_sum_vectors(
    discounts: Decimal128VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    row_count: usize,
) -> Result<Option<(f64, u64)>> {
    let mut sum = 0.0;
    let mut count = 0_u64;
    if discounts.null_count() == 0 && extendedprices.null_count() == 0 {
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        if discounts.precision() <= 18 && extendedprices.precision() <= 18 {
            for (&discount, &extendedprice) in discounts
                .raw_values()
                .iter()
                .zip(extendedprices.raw_values())
            {
                sum += (extendedprice as i64 * discount as i64) as f64 * revenue_scale;
                count += 1;
            }
            return Ok(Some((sum, count)));
        }
        for (&discount, &extendedprice) in discounts
            .raw_values()
            .iter()
            .zip(extendedprices.raw_values())
        {
            sum += (extendedprice * discount) as f64 * revenue_scale;
            count += 1;
        }
        return Ok(Some((sum, count)));
    }
    for row in 0..row_count {
        if discounts.is_null(row) || extendedprices.is_null(row) {
            continue;
        }
        sum += extendedprices.value(row) * discounts.value(row);
        count += 1;
    }
    Ok(Some((sum, count)))
}

fn q06_revenue_sum_batch(
    batch: RecordBatch,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<(f64, u64)>> {
    let shipdates = batch_column(&batch, "l_shipdate")?;
    let discounts = batch_column(&batch, "l_discount")?;
    let quantities = batch_column(&batch, "l_quantity")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    if let (Some(shipdates), Some(discounts), Some(quantities), Some(extendedprices)) = (
        shipdates.as_any().downcast_ref::<Date32Array>(),
        decimal_input(discounts)?,
        decimal_input(quantities)?,
        decimal_input(extendedprices)?,
    ) {
        let mut sum = 0.0;
        let mut count = 0_u64;
        if shipdates.null_count() == 0
            && discounts.null_count() == 0
            && quantities.null_count() == 0
            && extendedprices.null_count() == 0
        {
            let discount_low_raw = scaled_f64_to_i128(discount_low, discounts.scale);
            let discount_high_raw = scaled_f64_to_i128(discount_high, discounts.scale);
            let quantity_limit_raw = scaled_f64_to_i128(quantity_limit, quantities.scale);
            let revenue_scale = 1.0 / (extendedprices.scale * discounts.scale);
            let shipdate_values = shipdates.values().as_ref();
            let discount_values = discounts.raw_values();
            let quantity_values = quantities.raw_values();
            let extendedprice_values = extendedprices.raw_values();
            if discounts.precision <= 18
                && quantities.precision <= 18
                && extendedprices.precision <= 18
            {
                let discount_low_raw = discount_low_raw as i64;
                let discount_high_raw = discount_high_raw as i64;
                let quantity_limit_raw = quantity_limit_raw as i64;
                for row in 0..shipdate_values.len() {
                    let shipdate = shipdate_values[row];
                    let discount = discount_values[row] as i64;
                    if shipdate < start_days
                        || shipdate >= end_days
                        || discount < discount_low_raw
                        || discount > discount_high_raw
                        || (quantity_values[row] as i64) >= quantity_limit_raw
                    {
                        continue;
                    }
                    sum += ((extendedprice_values[row] as i64) * discount) as f64 * revenue_scale;
                    count += 1;
                }
                return Ok(Some((sum, count)));
            }
            for row in 0..shipdate_values.len() {
                let shipdate = shipdate_values[row];
                let discount = discount_values[row];
                if shipdate < start_days
                    || shipdate >= end_days
                    || discount < discount_low_raw
                    || discount > discount_high_raw
                    || quantity_values[row] >= quantity_limit_raw
                {
                    continue;
                }
                sum += (extendedprice_values[row] * discount) as f64 * revenue_scale;
                count += 1;
            }
            return Ok(Some((sum, count)));
        }
        for row in 0..batch.num_rows() {
            if shipdates.is_null(row)
                || discounts.is_null(row)
                || quantities.is_null(row)
                || extendedprices.is_null(row)
            {
                continue;
            }
            let shipdate = shipdates.value(row);
            let discount = discounts.value(row);
            if shipdate < start_days
                || shipdate >= end_days
                || discount < discount_low
                || discount > discount_high
                || quantities.value(row) >= quantity_limit
            {
                continue;
            }
            sum += extendedprices.value(row) * discount;
            count += 1;
        }
        return Ok(Some((sum, count)));
    }
    Ok(None)
}

fn q06_revenue_sum_view(
    view: BatchView<'_>,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<(f64, u64)>> {
    if view.num_columns() == 4 {
        let (Some(shipdates), Some(discounts), Some(quantities), Some(extendedprices)) = (
            view.date32_vector(0),
            view.decimal128_vector(1),
            view.decimal128_vector(2),
            view.decimal128_vector(3),
        ) else {
            let Some(batch) = view.try_record_batch() else {
                return Ok(None);
            };
            return q06_revenue_sum_batch(
                batch.clone(),
                start_days,
                end_days,
                discount_low,
                discount_high,
                quantity_limit,
            );
        };
        return q06_revenue_sum_vector_views(
            shipdates,
            discounts,
            quantities,
            extendedprices,
            view.num_rows(),
            start_days,
            end_days,
            discount_low,
            discount_high,
            quantity_limit,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q06_revenue_sum_batch(
        batch.clone(),
        start_days,
        end_days,
        discount_low,
        discount_high,
        quantity_limit,
    )
}

#[allow(clippy::too_many_arguments)]
fn q06_revenue_sum_vector_views(
    shipdates: Date32VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    row_count: usize,
    start_days: i32,
    end_days: i32,
    discount_low: f64,
    discount_high: f64,
    quantity_limit: f64,
) -> Result<Option<(f64, u64)>> {
    if let Some(shipdate_values) = shipdates.values_if_null_free()
        && discounts.null_count() == 0
        && quantities.null_count() == 0
        && extendedprices.null_count() == 0
    {
        let discount_low_raw = scaled_f64_to_i128(discount_low, discounts.scale());
        let discount_high_raw = scaled_f64_to_i128(discount_high, discounts.scale());
        let quantity_limit_raw = scaled_f64_to_i128(quantity_limit, quantities.scale());
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        let discount_values = discounts.raw_values();
        let quantity_values = quantities.raw_values();
        let extendedprice_values = extendedprices.raw_values();
        if discounts.precision() <= 18
            && quantities.precision() <= 18
            && extendedprices.precision() <= 18
        {
            return Ok(Some(vector_q06_revenue_sum_i64(
                shipdate_values,
                discount_values,
                quantity_values,
                extendedprice_values,
                start_days,
                end_days,
                discount_low_raw as i64,
                discount_high_raw as i64,
                quantity_limit_raw as i64,
                revenue_scale,
            )));
        }
        let mut sum = 0.0;
        let mut count = 0_u64;
        for row in 0..shipdate_values.len() {
            let shipdate = shipdate_values[row];
            let discount = discount_values[row];
            if shipdate < start_days
                || shipdate >= end_days
                || discount < discount_low_raw
                || discount > discount_high_raw
                || quantity_values[row] >= quantity_limit_raw
            {
                continue;
            }
            sum += (extendedprice_values[row] * discount) as f64 * revenue_scale;
            count += 1;
        }
        return Ok(Some((sum, count)));
    }
    let mut sum = 0.0;
    let mut count = 0_u64;
    for row in 0..row_count {
        if shipdates.is_null(row)
            || discounts.is_null(row)
            || quantities.is_null(row)
            || extendedprices.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        let discount = discounts.value(row);
        if shipdate < start_days
            || shipdate >= end_days
            || discount < discount_low
            || discount > discount_high
            || quantities.value(row) >= quantity_limit
        {
            continue;
        }
        sum += extendedprices.value(row) * discount;
        count += 1;
    }
    Ok(Some((sum, count)))
}

#[allow(clippy::too_many_arguments)]
fn vector_q06_revenue_sum_i64(
    shipdates: &[i32],
    discounts: &[i128],
    quantities: &[i128],
    extendedprices: &[i128],
    start_days: i32,
    end_days: i32,
    discount_low_raw: i64,
    discount_high_raw: i64,
    quantity_limit_raw: i64,
    revenue_scale: f64,
) -> (f64, u64) {
    let mut sum = 0.0;
    let mut count = 0_u64;
    for row in 0..shipdates.len() {
        let shipdate = shipdates[row];
        let discount = discounts[row] as i64;
        if shipdate < start_days
            || shipdate >= end_days
            || discount < discount_low_raw
            || discount > discount_high_raw
            || (quantities[row] as i64) >= quantity_limit_raw
        {
            continue;
        }
        sum += ((extendedprices[row] as i64) * discount) as f64 * revenue_scale;
        count += 1;
    }
    (sum, count)
}

fn scaled_f64_to_i128(value: f64, scale: f64) -> i128 {
    (value * scale).round() as i128
}

async fn try_execute_q07_volume_shipping_fast(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(outer_select) = query.body.as_ref() else {
        return Ok(None);
    };
    if !q07_outer_shape(outer_select, query) {
        return Ok(None);
    }
    let [table_with_joins] = outer_select.from.as_slice() else {
        return Ok(None);
    };
    if !table_with_joins.joins.is_empty() {
        return Ok(None);
    }
    let TableFactor::Derived {
        subquery,
        alias: Some(alias),
        ..
    } = &table_with_joins.relation
    else {
        return Ok(None);
    };
    if !alias.name.value.eq_ignore_ascii_case("shipping") {
        return Ok(None);
    }
    let SetExpr::Select(inner_select) = subquery.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = inner_select.selection.as_ref() else {
        return Ok(None);
    };
    if !q07_inner_shape(inner_select, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(outer_select)?;
    reject_select_features(inner_select)?;
    let Some(tables) = parse_comma_join_table_refs(inner_select)? else {
        return Ok(None);
    };
    if tables.len() != 6 {
        return Ok(None);
    }
    let mut supplier = None;
    let mut lineitem = None;
    let mut orders = None;
    let mut customer = None;
    let mut nation_tables = Vec::new();
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        } else if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("customer") {
            customer = Some(table);
        } else if alias.eq_ignore_ascii_case("n1") || alias.eq_ignore_ascii_case("n2") {
            nation_tables.push(table);
        }
    }
    let (Some(supplier), Some(lineitem), Some(orders), Some(customer)) =
        (supplier, lineitem, orders, customer)
    else {
        return Ok(None);
    };
    if nation_tables.is_empty() {
        return Ok(None);
    }
    if !supplier.path.exists() {
        return Err(DodamError::MissingPath(supplier.path));
    }
    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some((start_days, end_days)) = date_between_bounds(&conjuncts, "l_shipdate")? else {
        return Ok(None);
    };
    let nation_names = q10_nation_names(engine, nation_tables[0].path.clone(), batch_size).await?;
    let target_nations = nation_names
        .iter()
        .filter_map(|(key, name)| {
            (name == "FRANCE" || name == "GERMANY").then_some((*key, name.clone()))
        })
        .collect::<HashMap<_, _>>();
    if target_nations.len() != 2 {
        return Ok(Some(q07_output(Vec::new())?));
    }
    let suppliers =
        q07_supplier_nations(engine, supplier.path, batch_size, &target_nations).await?;
    if suppliers.is_empty() {
        return Ok(Some(q07_output(Vec::new())?));
    }
    let customers =
        q07_customer_nations(engine, customer.path, batch_size, &target_nations).await?;
    if customers.is_empty() {
        return Ok(Some(q07_output(Vec::new())?));
    }
    let order_customers = q07_order_customers(engine, orders.path, batch_size, &customers).await?;
    if order_customers.is_empty() {
        return Ok(Some(q07_output(Vec::new())?));
    }
    let rows = q07_volume_rows(
        engine,
        lineitem.path,
        batch_size,
        &suppliers,
        &order_customers,
        &target_nations,
        start_days,
        end_days,
    )
    .await?;
    Ok(Some(q07_output(rows)?))
}

fn q07_outer_shape(select: &Select, query: &Query) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let group_by = select.group_by.to_string().to_ascii_lowercase();
    let order_by = query
        .order_by
        .as_ref()
        .map(|order_by| order_by.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    select.from.len() == 1
        && select.projection.len() == 4
        && projection.contains("supp_nation")
        && projection.contains("cust_nation")
        && projection.contains("l_year")
        && projection.contains("sum(volume)")
        && group_by.contains("supp_nation")
        && group_by.contains("cust_nation")
        && group_by.contains("l_year")
        && order_by.contains("supp_nation")
        && order_by.contains("cust_nation")
        && order_by.contains("l_year")
}

fn q07_inner_shape(select: &Select, selection: &SqlExpr) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let selection = selection.to_string().to_ascii_lowercase();
    select.from.len() == 6
        && select.projection.len() == 4
        && projection.contains("n1.n_name as supp_nation")
        && projection.contains("n2.n_name as cust_nation")
        && projection.contains("extract(year from l_shipdate)")
        && projection.contains("l_extendedprice * (1 - l_discount)")
        && selection.contains("s_suppkey = l_suppkey")
        && selection.contains("o_orderkey = l_orderkey")
        && selection.contains("c_custkey = o_custkey")
        && selection.contains("s_nationkey = n1.n_nationkey")
        && selection.contains("c_nationkey = n2.n_nationkey")
        && selection.contains("france")
        && selection.contains("germany")
        && selection.contains("l_shipdate between")
}

fn date_between_bounds(conjuncts: &[SqlExpr], column: &str) -> Result<Option<(i32, i32)>> {
    for conjunct in conjuncts {
        let SqlExpr::Between {
            expr,
            low,
            high,
            negated,
        } = conjunct
        else {
            continue;
        };
        if *negated || !sql_expr_column_matches(expr, column) {
            continue;
        }
        return Ok(Some((literal_date_days(low)?, literal_date_days(high)?)));
    }
    Ok(None)
}

async fn q07_supplier_nations(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    target_nations: &HashMap<i64, String>,
) -> Result<FastHashMap<i64, i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["s_suppkey".to_string(), "s_nationkey".to_string()]),
            None,
        )
        .await?;
    let mut suppliers = fast_hash_map::<i64, i64>();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let suppkeys = batch_column(&batch, "s_suppkey")?;
        let nationkeys = batch_column(&batch, "s_nationkey")?;
        if let (Some(suppkeys), Some(nationkeys)) = (
            suppkeys.as_any().downcast_ref::<Int64Array>(),
            nationkeys.as_any().downcast_ref::<Int64Array>(),
        ) && suppkeys.null_count() == 0
            && nationkeys.null_count() == 0
        {
            let suppkey_values = suppkeys.values().as_ref();
            let nationkey_values = nationkeys.values().as_ref();
            for row in 0..suppkey_values.len() {
                let nationkey = nationkey_values[row];
                if target_nations.contains_key(&nationkey) {
                    suppliers.insert(suppkey_values[row], nationkey);
                }
            }
            continue;
        }
        for row in 0..batch.num_rows() {
            let (Some(suppkey), Some(nationkey)) = (
                numeric_i64_value(suppkeys, row)?,
                numeric_i64_value(nationkeys, row)?,
            ) else {
                continue;
            };
            if target_nations.contains_key(&nationkey) {
                suppliers.insert(suppkey, nationkey);
            }
        }
    }
    Ok(suppliers)
}

