async fn q07_order_customers(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_nations: &FastHashMap<i64, i64>,
) -> Result<FastHashMap<i64, i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["o_orderkey".to_string(), "o_custkey".to_string()]),
            None,
        )
        .await?;
    let customer_nations = Arc::new(AdaptiveI64Map::from_hash(customer_nations.clone()));
    parallel_batch_fold_view_chunks(
        &mut stream,
        4,
        || fast_hash_map::<i64, i64>(),
        move |view, orders| {
            merge_maps(orders, q07_order_customers_view(view, &customer_nations)?);
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<i64, i64>(),
        merge_maps,
        "Q07 order customer nations",
    )
}

fn q07_order_customers_batch(
    batch: RecordBatch,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, i64>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    if let Some(orders) = q07_order_customers_batch_typed(orderkeys, custkeys, customer_nations) {
        return Ok(orders);
    }
    let mut orders = fast_hash_map::<i64, i64>();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(custkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(custkeys, row)?,
        ) else {
            continue;
        };
        if let Some(nationkey) = customer_nations.get(custkey) {
            orders.insert(orderkey, nationkey);
        }
    }
    Ok(orders)
}

fn q07_order_customers_view(
    view: BatchView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, i64>> {
    if view.num_columns() == 2
        && let (Some(orderkeys), Some(custkeys)) = (view.i64_vector(0), view.i64_vector(1))
        && let Some(orders) =
            q07_order_customers_vector_typed(orderkeys, custkeys, customer_nations)
    {
        return Ok(orders);
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(fast_hash_map());
    };
    q07_order_customers_batch(batch.clone(), customer_nations)
}

fn q07_order_customers_batch_typed(
    orderkeys: &ArrayRef,
    custkeys: &ArrayRef,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Option<FastHashMap<i64, i64>> {
    let (Some(orderkeys), Some(custkeys)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        custkeys.as_any().downcast_ref::<Int64Array>(),
    ) else {
        return None;
    };
    let mut orders = fast_hash_map::<i64, i64>();
    if orderkeys.null_count() == 0 && custkeys.null_count() == 0 {
        for row in 0..orderkeys.len() {
            if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
                orders.insert(orderkeys.value(row), nationkey);
            }
        }
        return Some(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    Some(orders)
}

fn q07_order_customers_vector_typed(
    orderkeys: I64VectorView<'_>,
    custkeys: I64VectorView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Option<FastHashMap<i64, i64>> {
    let mut orders = fast_hash_map::<i64, i64>();
    if let (Some(orderkey_values), Some(custkey_values)) = (
        orderkeys.values_if_null_free(),
        custkeys.values_if_null_free(),
    ) {
        for row in 0..orderkey_values.len() {
            if let Some(nationkey) = customer_nations.get(custkey_values[row]) {
                orders.insert(orderkey_values[row], nationkey);
            }
        }
        return Some(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    Some(orders)
}

struct Q07Row {
    supp_nation: String,
    cust_nation: String,
    l_year: i32,
    revenue: f64,
}

async fn q07_volume_rows(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_nations: &FastHashMap<i64, i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    nation_names: &HashMap<i64, String>,
    start_days: i32,
    end_days: i32,
) -> Result<Vec<Q07Row>> {
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_suppkey".to_string(),
        "l_shipdate".to_string(),
        "l_extendedprice".to_string(),
        "l_discount".to_string(),
    ]);
    let mut pruning_predicates = if let Some((min_key, max_key)) =
        selective_i64_key_range(order_customer_nations.keys().copied())
    {
        i64_range_pruning_predicates("l_orderkey", min_key, max_key)
    } else {
        Vec::new()
    };
    pruning_predicates.push(Expr::Comparison(ComparisonExpr {
        column: "l_shipdate".to_string(),
        op: ComparisonOp::GtEq,
        value: LiteralValue::Int64(i64::from(start_days)),
    }));
    pruning_predicates.push(Expr::Comparison(ComparisonExpr {
        column: "l_shipdate".to_string(),
        op: ComparisonOp::LtEq,
        value: LiteralValue::Int64(i64::from(end_days)),
    }));
    let supplier_nations = Arc::new(AdaptiveI64Map::from_hash(supplier_nations.clone()));
    let order_customer_nations = Arc::new(order_customer_nations.clone());
    let groups = if q07_late_materialized_enabled()
        && let Some(groups) = q07_volume_rows_late_materialized(
            engine,
            path.clone(),
            batch_size,
            supplier_nations.clone(),
            order_customer_nations.clone(),
            start_days,
            end_days,
            pruning_predicates.clone(),
        )
        .await?
    {
        groups
    } else if q07_row_group_map_enabled() {
        let supplier_nations_for_scan = supplier_nations.clone();
        let order_customer_nations_for_scan = order_customer_nations.clone();
        if let Some(partials) = engine
            .parquet_row_group_map_pruned_view(
                path.clone(),
                batch_size,
                projection.clone(),
                pruning_predicates.clone(),
                q07_row_group_map_chunk(),
                fast_hash_map::<(i64, i64, i32), f64>,
                move |view, groups| {
                    merge_f64_groups(
                        groups,
                        q07_volume_projected_view(
                            view,
                            &supplier_nations_for_scan,
                            &order_customer_nations_for_scan,
                            start_days,
                            end_days,
                        )?,
                    );
                    Ok(Some(()))
                },
                |groups| Ok(Some(groups)),
            )
            .await?
        {
            let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
            for partial in partials {
                merge_f64_groups(&mut groups, partial);
            }
            groups
        } else {
            q07_volume_rows_stream(
                engine,
                path,
                batch_size,
                projection,
                pruning_predicates,
                supplier_nations,
                order_customer_nations,
                start_days,
                end_days,
            )
            .await?
        }
    } else {
        q07_volume_rows_stream(
            engine,
            path,
            batch_size,
            projection,
            pruning_predicates,
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        )
        .await?
    };
    let mut rows = groups
        .into_iter()
        .filter_map(|((supp_nation_key, cust_nation_key, l_year), revenue)| {
            Some(Q07Row {
                supp_nation: nation_names.get(&supp_nation_key)?.clone(),
                cust_nation: nation_names.get(&cust_nation_key)?.clone(),
                l_year,
                revenue,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        left.supp_nation
            .cmp(&right.supp_nation)
            .then_with(|| left.cust_nation.cmp(&right.cust_nation))
            .then_with(|| left.l_year.cmp(&right.l_year))
    });
    Ok(rows)
}

#[allow(clippy::too_many_arguments)]
async fn q07_volume_rows_late_materialized(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    start_days: i32,
    end_days: i32,
    pruning_predicates: Vec<Expr>,
) -> Result<Option<FastHashMap<(i64, i64, i32), f64>>> {
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec![
                "l_orderkey".to_string(),
                "l_suppkey".to_string(),
                "l_shipdate".to_string(),
            ]),
            Projection::Columns(vec![
                "l_extendedprice".to_string(),
                "l_discount".to_string(),
            ]),
            pruning_predicates,
            q07_late_materialized_row_group_chunk(),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                q07_late_materialized_max_selected_ratio(),
                q07_late_materialized_max_selector_run_ratio(),
            ),
            {
                let supplier_nations = supplier_nations.clone();
                let order_customer_nations = order_customer_nations.clone();
                move || Q07LateState {
                    supplier_nations: supplier_nations.clone(),
                    order_customer_nations: order_customer_nations.clone(),
                    selected_rows: Vec::new(),
                    payload_offset: 0,
                    groups: fast_hash_map(),
                    year_cache: Date32YearCache::default(),
                }
            },
            move |view, selection, state| {
                q07_late_build_selection_view(view, selection, state, start_days, end_days)
            },
            q07_late_consume_payload_view,
            |state, metrics| {
                if state.payload_offset != state.selected_rows.len() {
                    return Err(DodamError::UnsupportedSql(
                        "Q07 payload row mismatch".to_string(),
                    ));
                }
                Ok(Some((state.groups, metrics)))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        let (chunk_groups, chunk_metrics) = chunk.output;
        metrics.add(chunk_metrics);
        merge_f64_groups(&mut groups, chunk_groups);
    }
    q07_log_late_materialized_profile(metrics, q07_late_materialized_row_group_chunk());
    Ok(Some(groups))
}

fn q07_late_materialized_enabled() -> bool {
    if std::env::var("DODAM_Q07_DISABLE_LATE_MATERIALIZE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return false;
    }
    true
}

fn q07_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q07_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q07_late_materialized_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q07_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.10)
}

fn q07_late_materialized_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q07_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.60)
}

#[derive(Clone, Copy)]
struct Q07LateSelectedRow {
    supp_nation_key: i64,
    cust_nation_key: i64,
    shipdate: i32,
}

struct Q07LateState {
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    selected_rows: Vec<Q07LateSelectedRow>,
    payload_offset: usize,
    groups: FastHashMap<(i64, i64, i32), f64>,
    year_cache: Date32YearCache,
}

fn q07_late_build_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Result<Option<()>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    if let (Some(orderkeys), Some(suppkeys), Some(shipdates)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        shipdates.as_any().downcast_ref::<Date32Array>(),
    ) && orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && shipdates.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let shipdate_values = shipdates.values().as_ref();
        for row in 0..orderkey_values.len() {
            let shipdate = shipdate_values[row];
            let selected = if shipdate < start_days || shipdate > end_days {
                None
            } else {
                let supp_nation_key = state.supplier_nations.get(suppkey_values[row]);
                let cust_nation_key = state.order_customer_nations.get(&orderkey_values[row]);
                match (supp_nation_key, cust_nation_key) {
                    (Some(supp_nation_key), Some(cust_nation_key))
                        if supp_nation_key != *cust_nation_key =>
                    {
                        Some(Q07LateSelectedRow {
                            supp_nation_key,
                            cust_nation_key: *cust_nation_key,
                            shipdate,
                        })
                    }
                    _ => None,
                }
            };
            if let Some(row) = selected {
                selection.push(true);
                state.selected_rows.push(row);
            } else {
                selection.push(false);
            }
        }
        return Ok(Some(()));
    }
    for row in 0..batch.num_rows() {
        let selected = match (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            date32_value(shipdates, row)?,
        ) {
            (Some(orderkey), Some(suppkey), Some(shipdate))
                if shipdate >= start_days && shipdate <= end_days =>
            {
                let supp_nation_key = state.supplier_nations.get(suppkey);
                let cust_nation_key = state.order_customer_nations.get(&orderkey);
                match (supp_nation_key, cust_nation_key) {
                    (Some(supp_nation_key), Some(cust_nation_key))
                        if supp_nation_key != *cust_nation_key =>
                    {
                        Some(Q07LateSelectedRow {
                            supp_nation_key,
                            cust_nation_key: *cust_nation_key,
                            shipdate,
                        })
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        if let Some(row) = selected {
            selection.push(true);
            state.selected_rows.push(row);
        } else {
            selection.push(false);
        }
    }
    Ok(Some(()))
}

fn q07_late_build_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Result<Option<()>> {
    if view.num_columns() == 3
        && let (Some(orderkeys), Some(suppkeys), Some(shipdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
        )
    {
        if let (Some(orderkey_values), Some(suppkey_values), Some(shipdate_values)) = (
            orderkeys.values_if_null_free(),
            suppkeys.values_if_null_free(),
            shipdates.values_if_null_free(),
        ) {
            for row in 0..orderkey_values.len() {
                let selected = q07_late_selected_row(
                    orderkey_values[row],
                    suppkey_values[row],
                    shipdate_values[row],
                    state,
                    start_days,
                    end_days,
                );
                if let Some(row) = selected {
                    selection.push(true);
                    state.selected_rows.push(row);
                } else {
                    selection.push(false);
                }
            }
            return Ok(Some(()));
        }
        for row in 0..orderkeys.len() {
            let selected =
                if orderkeys.is_null(row) || suppkeys.is_null(row) || shipdates.is_null(row) {
                    None
                } else {
                    q07_late_selected_row(
                        orderkeys.value(row),
                        suppkeys.value(row),
                        shipdates.value(row),
                        state,
                        start_days,
                        end_days,
                    )
                };
            if let Some(row) = selected {
                selection.push(true);
                state.selected_rows.push(row);
            } else {
                selection.push(false);
            }
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q07_late_build_selection_batch(batch.clone(), selection, state, start_days, end_days)
}

fn q07_late_selected_row(
    orderkey: i64,
    suppkey: i64,
    shipdate: i32,
    state: &Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Option<Q07LateSelectedRow> {
    if shipdate < start_days || shipdate > end_days {
        return None;
    }
    let supp_nation_key = state.supplier_nations.get(suppkey)?;
    let cust_nation_key = *state.order_customer_nations.get(&orderkey)?;
    (supp_nation_key != cust_nation_key).then_some(Q07LateSelectedRow {
        supp_nation_key,
        cust_nation_key,
        shipdate,
    })
}

fn q07_late_consume_payload_batch(
    batch: RecordBatch,
    state: &mut Q07LateState,
) -> Result<Option<()>> {
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let (Some(extendedprices), Some(discounts)) =
        (decimal_input(extendedprices)?, decimal_input(discounts)?)
    {
        if extendedprices.null_count() == 0 && discounts.null_count() == 0 {
            let extendedprice_values = extendedprices.raw_values();
            let discount_values = discounts.raw_values();
            let (discount_scale, revenue_scale) =
                decimal_discounted_revenue_scales(extendedprices, discounts);
            for row in 0..extendedprice_values.len() {
                let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
                    return Err(DodamError::UnsupportedSql(
                        "Q07 payload row overflow".to_string(),
                    ));
                };
                state.payload_offset += 1;
                *state
                    .groups
                    .entry((
                        selected.supp_nation_key,
                        selected.cust_nation_key,
                        state.year_cache.year(selected.shipdate)?,
                    ))
                    .or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
            return Ok(Some(()));
        }
    }
    for row in 0..batch.num_rows() {
        let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
            return Err(DodamError::UnsupportedSql(
                "Q07 payload row overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        *state
            .groups
            .entry((
                selected.supp_nation_key,
                selected.cust_nation_key,
                state.year_cache.year(selected.shipdate)?,
            ))
            .or_insert(0.0) += extendedprice * (1.0 - discount);
    }
    Ok(Some(()))
}

fn q07_late_consume_payload_view(
    view: BatchView<'_>,
    state: &mut Q07LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 2
        && let (Some(extendedprices), Some(discounts)) =
            (view.decimal128_vector(0), view.decimal128_vector(1))
    {
        q07_late_consume_payload_vector(extendedprices, discounts, state)?;
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q07_late_consume_payload_batch(batch.clone(), state)
}

fn q07_late_consume_payload_vector(
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    state: &mut Q07LateState,
) -> Result<()> {
    if extendedprices.null_count() == 0 && discounts.null_count() == 0 {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        for row in 0..extendedprice_values.len() {
            let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
                return Err(DodamError::UnsupportedSql(
                    "Q07 payload row overflow".to_string(),
                ));
            };
            state.payload_offset += 1;
            *state
                .groups
                .entry((
                    selected.supp_nation_key,
                    selected.cust_nation_key,
                    state.year_cache.year(selected.shipdate)?,
                ))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(());
    }
    for row in 0..extendedprices.raw_values().len() {
        let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
            return Err(DodamError::UnsupportedSql(
                "Q07 payload row overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        if extendedprices.is_null(row) || discounts.is_null(row) {
            continue;
        }
        *state
            .groups
            .entry((
                selected.supp_nation_key,
                selected.cust_nation_key,
                state.year_cache.year(selected.shipdate)?,
            ))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(())
}

fn q07_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q07 lineitem: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

#[allow(clippy::too_many_arguments)]
async fn q07_volume_rows_stream(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    pruning_predicates: Vec<Expr>,
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let mut stream = if pruning_predicates.is_empty() {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    } else {
        engine
            .scan_parquet_batches_pruned(path, batch_size, projection, pruning_predicates)
            .await?
    };
    parallel_batch_fold_view_chunks(
        &mut stream,
        join_aggregate_chunk_size(),
        || fast_hash_map::<(i64, i64, i32), f64>(),
        move |view, groups| {
            merge_f64_groups(
                groups,
                q07_volume_projected_view(
                    view,
                    &supplier_nations,
                    &order_customer_nations,
                    start_days,
                    end_days,
                )?,
            );
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<(i64, i64, i32), f64>(),
        merge_f64_groups,
        "Q07 volume aggregate",
    )
}

fn q07_row_group_map_enabled() -> bool {
    std::env::var_os("DODAM_Q07_DISABLE_ROW_GROUP_MAP").is_none()
}

fn q07_row_group_map_chunk() -> usize {
    std::env::var("DODAM_Q07_ROW_GROUP_MAP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q07_volume_batch(
    batch: RecordBatch,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let Some(groups) = q07_volume_batch_typed(
        orderkeys,
        suppkeys,
        shipdates,
        extendedprices,
        discounts,
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )? {
        return Ok(groups);
    }
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(suppkey), Some(shipdate)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            date32_value(shipdates, row)?,
        ) else {
            continue;
        };
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkey),
            order_customer_nations.get(&orderkey).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprice * (1.0 - discount);
    }
    Ok(groups)
}

#[allow(dead_code)]
fn q07_volume_projected_batch(
    batch: RecordBatch,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    if batch.num_columns() == 5
        && let Some(groups) = q07_volume_batch_typed(
            batch.column(0),
            batch.column(1),
            batch.column(2),
            batch.column(3),
            batch.column(4),
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        )?
    {
        return Ok(groups);
    }
    q07_volume_batch(
        batch,
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )
}

fn q07_volume_projected_view(
    view: BatchView<'_>,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    if view.num_columns() == 5
        && let (
            Some(orderkeys),
            Some(suppkeys),
            Some(shipdates),
            Some(extendedprices),
            Some(discounts),
        ) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
            view.decimal128_vector(3),
            view.decimal128_vector(4),
        )
    {
        return q07_volume_vector(
            orderkeys,
            suppkeys,
            shipdates,
            extendedprices,
            discounts,
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q07 volume raw vector columns have unsupported types".to_string(),
        ));
    };
    q07_volume_batch(
        batch.clone(),
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )
}

#[allow(clippy::too_many_arguments)]
fn q07_volume_vector(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    shipdates: Date32VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    if let (Some(orderkey_values), Some(suppkey_values), Some(shipdate_values)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
        shipdates.values_if_null_free(),
    ) && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        if let Some((supplier_nation_values, supplier_nation_present)) =
            supplier_nations.dense_slices()
        {
            for row in 0..orderkey_values.len() {
                let shipdate = shipdate_values[row];
                if shipdate < start_days || shipdate > end_days {
                    continue;
                }
                let Ok(suppkey) = usize::try_from(suppkey_values[row]) else {
                    continue;
                };
                if !supplier_nation_present
                    .get(suppkey)
                    .copied()
                    .unwrap_or(false)
                {
                    continue;
                }
                let Some(cust_nation_key) =
                    order_customer_nations.get(&orderkey_values[row]).copied()
                else {
                    continue;
                };
                let supp_nation_key = supplier_nation_values[suppkey];
                if supp_nation_key == cust_nation_key {
                    continue;
                }
                *groups
                    .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                    .or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
            return Ok(groups);
        }
        for row in 0..orderkey_values.len() {
            let shipdate = shipdate_values[row];
            if shipdate < start_days || shipdate > end_days {
                continue;
            }
            let (Some(supp_nation_key), Some(cust_nation_key)) = (
                supplier_nations.get(suppkey_values[row]),
                order_customer_nations.get(&orderkey_values[row]).copied(),
            ) else {
                continue;
            };
            if supp_nation_key == cust_nation_key {
                continue;
            }
            *groups
                .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(groups);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || shipdates.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkeys.value(row)),
            order_customer_nations.get(&orderkeys.value(row)).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(groups)
}

fn q07_volume_batch_typed(
    orderkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    shipdates: &ArrayRef,
    extendedprices: &ArrayRef,
    discounts: &ArrayRef,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<Option<FastHashMap<(i64, i64, i32), f64>>> {
    let (Some(orderkeys), Some(suppkeys), Some(shipdates), Some(extendedprices), Some(discounts)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        shipdates.as_any().downcast_ref::<Date32Array>(),
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && shipdates.null_count() == 0
        && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let shipdate_values = shipdates.values().as_ref();
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let (discount_scale, revenue_scale) =
            decimal_discounted_revenue_scales(extendedprices, discounts);
        for row in 0..orderkeys.len() {
            let shipdate = shipdate_values[row];
            if shipdate < start_days || shipdate > end_days {
                continue;
            }
            let (Some(supp_nation_key), Some(cust_nation_key)) = (
                supplier_nations.get(suppkey_values[row]),
                order_customer_nations.get(&orderkey_values[row]).copied(),
            ) else {
                continue;
            };
            if supp_nation_key == cust_nation_key {
                continue;
            }
            *groups
                .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(Some(groups));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || shipdates.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkeys.value(row)),
            order_customer_nations.get(&orderkeys.value(row)).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(Some(groups))
}

fn q07_output(rows: Vec<Q07Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("supp_nation", DataType::Utf8, false),
            Field::new("cust_nation", DataType::Utf8, false),
            Field::new("l_year", DataType::Int64, false),
            Field::new("revenue", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.supp_nation.as_str()),
            )),
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.cust_nation.as_str()),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| i64::from(row.l_year)),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.revenue),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

async fn try_execute_q08_national_market_share_fast(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(outer_select) = query.body.as_ref() else {
        return Ok(None);
    };
    if !q08_outer_shape(outer_select, query) {
        return Ok(None);
    }
    let Some((inner_query, alias)) = parse_derived_from(outer_select)? else {
        return Ok(None);
    };
    if !alias.eq_ignore_ascii_case("all_nations") {
        return Ok(None);
    }
    let SetExpr::Select(inner_select) = inner_query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = inner_select.selection.as_ref() else {
        return Ok(None);
    };
    if !q08_inner_shape(inner_select, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(outer_select)?;
    reject_select_features(inner_select)?;
    let Some(tables) = parse_comma_join_table_refs(inner_select)? else {
        return Ok(None);
    };
    let mut part = None;
    let mut supplier = None;
    let mut lineitem = None;
    let mut orders = None;
    let mut customer = None;
    let mut n1 = None;
    let mut n2 = None;
    let mut region = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("part") {
            part = Some(table);
        } else if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        } else if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("customer") {
            customer = Some(table);
        } else if alias.eq_ignore_ascii_case("n1") {
            n1 = Some(table);
        } else if alias.eq_ignore_ascii_case("n2") {
            n2 = Some(table);
        } else if alias.eq_ignore_ascii_case("region") {
            region = Some(table);
        }
    }
    let (
        Some(part),
        Some(supplier),
        Some(lineitem),
        Some(orders),
        Some(customer),
        Some(n1),
        Some(n2),
        Some(region),
    ) = (part, supplier, lineitem, orders, customer, n1, n2, region)
    else {
        return Ok(None);
    };

    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some(region_name) = string_equality_literal(&conjuncts, "r_name")? else {
        return Ok(None);
    };
    let Some(part_type) = string_equality_literal(&conjuncts, "p_type")? else {
        return Ok(None);
    };
    let Some((start_days, end_days)) = date_between_bounds(&conjuncts, "o_orderdate")? else {
        return Ok(None);
    };

    if !part.path.exists() {
        return Err(DodamError::MissingPath(part.path));
    }
    let region_keys = q05_region_keys(engine, region.path, batch_size, &region_name).await?;
    if region_keys.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let customer_nations = q05_nation_names(engine, n1.path, batch_size, &region_keys).await?;
    if customer_nations.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let customers =
        q05_customer_nations(engine, customer.path, batch_size, &customer_nations).await?;
    if customers.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let orders = q08_order_years(
        engine,
        orders.path,
        batch_size,
        &customers,
        start_days,
        end_days,
    )
    .await?;
    if orders.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let part_keys = q08_part_keys(engine, part.path, batch_size, &part_type).await?;
    if part_keys.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let nation_names = q10_nation_names(engine, n2.path, batch_size).await?;
    let supplier_is_brazil =
        q08_supplier_is_brazil(engine, supplier.path, batch_size, &nation_names).await?;
    if supplier_is_brazil.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let mut rows = q08_market_share_rows(
        engine,
        lineitem.path,
        batch_size,
        &orders,
        &part_keys,
        &supplier_is_brazil,
    )
    .await?;
    rows.sort_by(|left, right| left.o_year.cmp(&right.o_year));
    Ok(Some(q08_output(rows)?))
}

fn q08_outer_shape(select: &Select, query: &Query) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let group_by = select.group_by.to_string().to_ascii_lowercase();
    let order_by = query
        .order_by
        .as_ref()
        .map(|order_by| order_by.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    select.from.len() == 1
        && projection.contains("o_year")
        && projection.contains("mkt_share")
        && projection.contains("nation = 'brazil'")
        && group_by.contains("o_year")
        && order_by.contains("o_year")
}

fn q08_inner_shape(select: &Select, selection: &SqlExpr) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let selection = selection.to_string().to_ascii_lowercase();
    select.from.len() == 8
        && projection.contains("extract(year from o_orderdate)")
        && projection.contains("l_extendedprice * (1 - l_discount)")
        && projection.contains("n2.n_name as nation")
        && selection.contains("p_partkey = l_partkey")
        && selection.contains("s_suppkey = l_suppkey")
        && selection.contains("l_orderkey = o_orderkey")
        && selection.contains("o_custkey = c_custkey")
        && selection.contains("c_nationkey = n1.n_nationkey")
        && selection.contains("n1.n_regionkey = r_regionkey")
        && selection.contains("s_nationkey = n2.n_nationkey")
        && selection.contains("o_orderdate between")
        && selection.contains("p_type")
}

async fn q08_part_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    part_type: &str,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["p_partkey".to_string(), "p_type".to_string()]),
            None,
        )
        .await?;
    let mut keys = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        q08_part_keys_view_into(BatchView::new(&batch), part_type, &mut keys)?;
    }
    Ok(keys)
}

fn q08_part_keys_view_into(
    view: BatchView<'_>,
    part_type: &str,
    keys: &mut HashSet<i64>,
) -> Result<()> {
    if view.num_columns() == 2
        && let (Ok(partkeys), Ok(types)) = (view.required_i64(0), view.required_utf8(1))
    {
        for row in 0..view.num_rows() {
            if partkeys.is_valid(row) && types.is_valid(row) && types.value(row) == part_type {
                keys.insert(partkeys.value(row));
            }
        }
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 part-key raw vector columns have unsupported types".to_string(),
        ));
    };
    let partkeys = batch_column(batch, "p_partkey")?;
    let types = batch_string_column(batch, "p_type")?;
    for row in 0..batch.num_rows() {
        if types.is_valid(row)
            && types.value(row) == part_type
            && let Some(partkey) = numeric_i64_value(partkeys, row)?
        {
            keys.insert(partkey);
        }
    }
    Ok(())
}

async fn q08_order_years(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "o_orderkey".to_string(),
                "o_custkey".to_string(),
                "o_orderdate".to_string(),
            ]),
            None,
        )
        .await?;
    let customer_nations = Arc::new(AdaptiveI64Map::from_hash(customer_nations.clone()));
    parallel_batch_fold_view_chunks(
        &mut stream,
        4,
        HashMap::<i64, i32>::new,
        move |view, orders| {
            merge_maps(
                orders,
                q08_order_years_view(view, &customer_nations, start_days, end_days)?,
            );
            Ok(Some(()))
        },
        Ok,
        HashMap::<i64, i32>::new(),
        merge_maps,
        "Q08 order years",
    )
}

fn q08_order_years_batch(
    batch: RecordBatch,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    let orderdates = batch_column(&batch, "o_orderdate")?;
    if let Some(orders) = q08_order_years_batch_typed(
        orderkeys,
        custkeys,
        orderdates,
        customer_nations,
        start_days,
        end_days,
    )? {
        return Ok(orders);
    }
    let mut orders = HashMap::new();
    let mut year_cache = Date32YearCache::default();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(custkey), Some(orderdate)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(custkeys, row)?,
            date32_value(orderdates, row)?,
        ) else {
            continue;
        };
        if orderdate >= start_days
            && orderdate <= end_days
            && customer_nations.get(custkey).is_some()
        {
            orders.insert(orderkey, year_cache.year(orderdate)?);
        }
    }
    Ok(orders)
}

fn q08_order_years_view(
    view: BatchView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    if view.num_columns() == 3
        && let (Some(orderkeys), Some(custkeys), Some(orderdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
        )
    {
        return q08_order_years_vector(
            orderkeys,
            custkeys,
            orderdates,
            customer_nations,
            start_days,
            end_days,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 order year raw vector columns have unsupported types".to_string(),
        ));
    };
    q08_order_years_batch(batch.clone(), customer_nations, start_days, end_days)
}

fn q08_order_years_vector(
    orderkeys: I64VectorView<'_>,
    custkeys: I64VectorView<'_>,
    orderdates: Date32VectorView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let mut orders = HashMap::new();
    let mut year_cache = Date32YearCache::default();
    if let (Some(orderkey_values), Some(custkey_values), Some(orderdate_values)) = (
        orderkeys.values_if_null_free(),
        custkeys.values_if_null_free(),
        orderdates.values_if_null_free(),
    ) {
        if let Some((_nation_values, nation_present)) = customer_nations.dense_slices() {
            for row in 0..orderkey_values.len() {
                let orderdate = orderdate_values[row];
                if orderdate < start_days || orderdate > end_days {
                    continue;
                }
                let Ok(custkey) = usize::try_from(custkey_values[row]) else {
                    continue;
                };
                if nation_present.get(custkey).copied().unwrap_or(false) {
                    orders.insert(orderkey_values[row], year_cache.year(orderdate)?);
                }
            }
            return Ok(orders);
        }
        for row in 0..orderkey_values.len() {
            let orderdate = orderdate_values[row];
            if orderdate >= start_days
                && orderdate <= end_days
                && customer_nations.get(custkey_values[row]).is_some()
            {
                orders.insert(orderkey_values[row], year_cache.year(orderdate)?);
            }
        }
        return Ok(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) || orderdates.is_null(row) {
            continue;
        }
        let orderdate = orderdates.value(row);
        if orderdate >= start_days
            && orderdate <= end_days
            && customer_nations.get(custkeys.value(row)).is_some()
        {
            orders.insert(orderkeys.value(row), year_cache.year(orderdate)?);
        }
    }
    Ok(orders)
}

